begin;
select no_plan();
update public.barangay_localities set resident_registration_enabled=false;
insert into public.barangays(id,name) values ('a6080000-0000-0000-0000-000000000001','Profile Conflict Local');
insert into public.barangay_localities values ('a6080000-0000-0000-0000-000000000001','Ampid 1','San Mateo','Rizal',true);
insert into auth.users(id,email,raw_user_meta_data) values
 ('b6080000-0000-0000-0000-000000000001','phase2-conflict@local.test','{"resident_registration_origin":"email_otp"}'),
 ('b6080000-0000-0000-0000-000000000002','phase2-other@local.test','{}');
select ok(not has_function_privilege('anon','public.complete_resident_profile_if_unchanged(jsonb,jsonb)','EXECUTE'),'No anonymous completion');
select ok(not has_function_privilege('service_role','public.complete_resident_profile_if_unchanged(jsonb,jsonb)','EXECUTE'),'No service-role shortcut');
set local role authenticated;
select set_config('request.jwt.claim.sub','b6080000-0000-0000-0000-000000000001',true);
select throws_ok($$select public.complete_resident_profile_if_unchanged('{}','[]')$$,'22023','invalid_profile_snapshot','Malformed snapshot rejected');
select lives_ok($$select public.complete_resident_profile_if_unchanged('{"firstName":"Phase","lastName":"Resident","houseNo":"12","street":"Main","sex":"female","employmentStatus":"student","mobileNumber":"09171234567","birthDate":"2000-01-01"}',null)$$,'Caller with no profile can complete with null snapshot');
select is(public.get_resident_account_setup_status()->'profileComplete','true'::jsonb,'Lifecycle reader sees atomic completion');
select throws_ok($$select public.complete_resident_profile_if_unchanged('{"firstName":"Phase","lastName":"Resident","houseNo":"13","street":"Main","sex":"female","employmentStatus":"student","mobileNumber":"09171234567","birthDate":"2000-01-01"}',null)$$,'PT409','resident_profile_changed','Null snapshot cannot overwrite a concurrently created profile');
select is((select house_no from public.profiles where id=auth.uid()),'12','Conflict makes no write');
select lives_ok($$select public.complete_resident_profile_if_unchanged('{"firstName":"Phase","lastName":"Resident","houseNo":"14","street":"Main","sex":"female","employmentStatus":"student","mobileNumber":"09171234567","birthDate":"2000-01-01"}',(select to_jsonb(p) from public.profiles p where id=auth.uid()))$$,'Exact current snapshot saves');
select lives_ok($$select public.complete_resident_profile('{"firstName":"Phase","lastName":"Resident","houseNo":"15","street":"Main","sex":"female","employmentStatus":"student","mobileNumber":"09171234567","birthDate":"2000-01-01"}')$$,'Older caller completion remains compatible');
select throws_ok($$select public.complete_resident_profile_if_unchanged('{"userId":"b6080000-0000-0000-0000-000000000002"}',(select to_jsonb(p) from public.profiles p where id=auth.uid()))$$,'22023',null,'Caller cannot supply an identity');
select throws_ok($$select public.complete_resident_profile_if_unchanged('{"barangayId":"a6080000-0000-0000-0000-000000000001"}',(select to_jsonb(p) from public.profiles p where id=auth.uid()))$$,'22023',null,'Caller cannot supply a tenant');
select is((select barangay_id::text from public.profiles where id=auth.uid()),'a6080000-0000-0000-0000-000000000001','Server preserves configured tenant');
select set_config('request.jwt.claim.sub','',true);
select throws_ok($$select public.complete_resident_profile_if_unchanged('{}',null)$$,'42501','resident_identity_required','Absent identity denied');
reset role;
update auth.users set banned_until=now()+interval '1 hour' where id='b6080000-0000-0000-0000-000000000001';
set local role authenticated;
select set_config('request.jwt.claim.sub','b6080000-0000-0000-0000-000000000001',true);
select throws_ok($$select public.complete_resident_profile_if_unchanged('{}',null)$$,'42501','resident_identity_required','Banned account denied before comparison');
reset role;
update auth.users set banned_until=null where id='b6080000-0000-0000-0000-000000000001';
select set_config('request.jwt.claim.sub','',true);
update public.profiles set role='admin' where id='b6080000-0000-0000-0000-000000000001';
set local role authenticated;
select set_config('request.jwt.claim.sub','b6080000-0000-0000-0000-000000000001',true);
select throws_ok($$select public.complete_resident_profile_if_unchanged('{}',null)$$,'42501','forbidden','Staff role cannot be converted');
reset role;
update public.profiles set role='resident',deleted_at=now() where id='b6080000-0000-0000-0000-000000000001';
set local role authenticated;
select throws_ok($$select public.complete_resident_profile_if_unchanged('{}',null)$$,'42501','forbidden','Soft-deleted profile denied');
reset role;
select * from finish();
rollback;
